      console.log('Suggested Refinements:', refinements);
      const apply = options.autoApply || /* prompt user for confirmation */;
      if (apply) {
        Object.assign(task, refinements);
        task.history.push({ timestamp: new Date(), feedback: options.feedback, changes: refinements });
        await saveTasks(tasks, options.taskFile);
        console.log('Task refined and history updated');
      }
